import hashlib,os,pathlib,re,tempfile
_VERSION=b"version https://git-lfs.github.com/spec/v1"
_OID=re.compile(rb"oid sha256:([0-9a-f]{64})")
_SIZE=re.compile(rb"size ([0-9]+)")

def inspect_model(path):
    path=pathlib.Path(path)
    data=path.read_bytes()
    lines=data.splitlines()
    if lines and lines[0]==_VERSION:
        if len(lines)!=3:raise ValueError("malformed LFS pointer")
        oid=_OID.fullmatch(lines[1]);size=_SIZE.fullmatch(lines[2])
        if not oid or not size:raise ValueError("malformed LFS pointer metadata")
        return {"status":"pointer","loadable":False,"sha256":oid.group(1).decode(),"size":int(size.group(1))}
    return {"status":"artifact","loadable":True,"sha256":hashlib.sha256(data).hexdigest(),"size":len(data)}

def restore_model(pointer_path,object_path):
    pointer_path=pathlib.Path(pointer_path);object_path=pathlib.Path(object_path)
    metadata=inspect_model(pointer_path)
    if metadata["status"]!="pointer":raise ValueError("target is not an LFS pointer")
    data=object_path.read_bytes()
    if len(data)!=metadata["size"] or hashlib.sha256(data).hexdigest()!=metadata["sha256"]:
        raise ValueError("object does not match pointer oid/size")
    temporary=None
    try:
        with tempfile.NamedTemporaryFile(mode="wb",dir=pointer_path.parent,prefix="."+pointer_path.name+".",suffix=".tmp",delete=False) as stream:
            temporary=pathlib.Path(stream.name);stream.write(data);stream.flush();os.fsync(stream.fileno())
        os.replace(temporary,pointer_path);temporary=None
    finally:
        if temporary is not None:temporary.unlink(missing_ok=True)
    return inspect_model(pointer_path)
```

